-- EduLK catalog, learning records, billing flags, ads and inbox.
create table if not exists grades (
  id serial primary key,
  number int not null unique,
  slug text not null unique,
  name_en text not null,
  name_si text not null,
  name_ta text not null,
  band text not null,
  sort_order int not null,
  is_active boolean not null default true
);
create table if not exists subjects (
  id serial primary key,
  grade_id int not null references grades(id) on delete cascade,
  slug text not null,
  name_en text not null,
  name_si text not null,
  name_ta text not null,
  icon text not null,
  color text not null,
  sort_order int not null,
  is_active boolean not null default true,
  unique (grade_id, slug)
);
create table if not exists videos (
  id serial primary key,
  youtube_id text not null unique,
  source_url text not null,
  title_en text not null,
  channel_name text not null default '',
  thumbnail_url text not null default '',
  permission_status text not null default 'unknown',
  link_status text not null default 'unchecked',
  created_at timestamptz not null default now()
);
create table if not exists lessons (
  id serial primary key,
  grade_id int not null references grades(id) on delete cascade,
  subject_id int not null references subjects(id) on delete cascade,
  video_id int references videos(id) on delete set null,
  slug text not null unique,
  title_en text not null,
  title_si text not null,
  title_ta text not null,
  summary_en text not null default '',
  summary_si text not null default '',
  summary_ta text not null default '',
  notes_en text not null default '',
  notes_si text not null default '',
  notes_ta text not null default '',
  tier_required text not null default 'free',
  status text not null default 'published',
  sort_order int not null default 0,
  is_featured boolean not null default false
);
create table if not exists quizzes (
  id serial primary key,
  lesson_id int not null unique references lessons(id) on delete cascade,
  pass_percent int not null default 60
);
create table if not exists quiz_questions (
  id serial primary key,
  quiz_id int not null references quizzes(id) on delete cascade,
  prompt_en text not null,
  prompt_si text not null,
  prompt_ta text not null,
  choices_en text not null,
  choices_si text not null,
  choices_ta text not null,
  correct_index int not null,
  sort_order int not null
);
create table if not exists profiles (
  user_id text primary key,
  role text not null default 'student',
  tier text not null default 'free',
  tier_expires_at timestamptz,
  banned_at timestamptz,
  created_at timestamptz not null default now()
);
create table if not exists bookmarks (
  user_id text not null,
  lesson_id int not null references lessons(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, lesson_id)
);
create table if not exists watch_history (
  user_id text not null,
  lesson_id int not null references lessons(id) on delete cascade,
  position_seconds int not null default 0,
  completed boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (user_id, lesson_id)
);
create table if not exists student_notes (
  user_id text not null,
  lesson_id int not null references lessons(id) on delete cascade,
  body text not null default '',
  updated_at timestamptz not null default now(),
  primary key (user_id, lesson_id)
);
create table if not exists quiz_attempts (
  id serial primary key,
  user_id text not null,
  quiz_id int not null references quizzes(id) on delete cascade,
  score_percent int not null,
  passed boolean not null,
  created_at timestamptz not null default now()
);
create table if not exists contact_messages (
  id serial primary key,
  name text not null,
  email text not null,
  reason text not null,
  message text not null,
  status text not null default 'new',
  created_at timestamptz not null default now()
);
create table if not exists ad_units (
  id serial primary key,
  name text not null,
  provider text not null default 'adsense',
  code text not null default '',
  placement text not null,
  frequency text not null default 'always',
  every_n int not null default 1,
  is_enabled boolean not null default true
);
create table if not exists announcements (
  id serial primary key,
  title_en text not null,
  title_si text not null,
  title_ta text not null,
  body_en text not null,
  body_si text not null,
  body_ta text not null,
  is_active boolean not null default true
);
create table if not exists activity_logs (
  id serial primary key,
  actor_id text not null,
  action text not null,
  entity_type text not null,
  entity_id text not null default '',
  created_at timestamptz not null default now()
);
