insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 1), (select id from subjects where grade_id = (select id from grades where number = 1) and slug = 'mathematics'), (select id from videos where youtube_id = '8mC59Fi_grA'), 'counting-to-20', 'Counting to 20', '20 දක්වා ගණන් කිරීම', '20 வரை எண்ணுதல்', 'Touch each object once. The last number you say is how many there are.', '20 දක්වා ගණන් කිරීම', '20 வரை எண்ணுதல்', 'Touch each object once. The last number you say is how many there are. Write one example in your own words before you leave the page.', '20 දක්වා ගණන් කිරීම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', '20 வரை எண்ணுதல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, true);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 1), (select id from subjects where grade_id = (select id from grades where number = 1) and slug = 'mathematics'), (select id from videos where youtube_id = 'V2piUc4CST4'), 'shapes-at-home', 'Shapes at home', 'නිවසේ හැඩතල', 'வீட்டில் உள்ள வடிவங்கள்', 'A door is a rectangle and a plate is a circle. Name five shapes you can touch.', 'නිවසේ හැඩතල', 'வீட்டில் உள்ள வடிவங்கள்', 'A door is a rectangle and a plate is a circle. Name five shapes you can touch. Write one example in your own words before you leave the page.', 'නිවසේ හැඩතල. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'வீட்டில் உள்ள வடிவங்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 1), (select id from subjects where grade_id = (select id from grades where number = 1) and slug = 'environment'), (select id from videos where youtube_id = '1axhVwYcvV0'), 'living-things-and-cells', 'Living things and cells', 'ජීවීන් සහ සෛල', 'உயிரிகளும் செல்களும்', 'Every living thing is made of cells. A cell is the smallest unit that is alive.', 'ජීවීන් සහ සෛල', 'உயிரிகளும் செல்களும்', 'Every living thing is made of cells. A cell is the smallest unit that is alive. Write one example in your own words before you leave the page.', 'ජීවීන් සහ සෛල. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'உயிரிகளும் செல்களும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, true);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 1), (select id from subjects where grade_id = (select id from grades where number = 1) and slug = 'environment'), null, 'water-at-home', 'Water at home', 'නිවසේ ජලය', 'வீட்டில் நீர்', 'List where water enters your home and where it leaves. Nothing on that list should be wasted.', 'නිවසේ ජලය', 'வீட்டில் நீர்', 'List where water enters your home and where it leaves. Nothing on that list should be wasted. Write one example in your own words before you leave the page.', 'නිවසේ ජලය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'வீட்டில் நீர். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 1), (select id from subjects where grade_id = (select id from grades where number = 1) and slug = 'english'), null, 'letters-and-sounds', 'Letters and sounds', 'අකුරු සහ ශබ්ද', 'எழுத்துகளும் ஒலிகளும்', 'Say the sound, then the letter name. Cat starts with the /k/ sound.', 'අකුරු සහ ශබ්ද', 'எழுத்துகளும் ஒலிகளும்', 'Say the sound, then the letter name. Cat starts with the /k/ sound. Write one example in your own words before you leave the page.', 'අකුරු සහ ශබ්ද. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'எழுத்துகளும் ஒலிகளும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 1), (select id from subjects where grade_id = (select id from grades where number = 1) and slug = 'english'), null, 'naming-words', 'Naming words', 'නම් පද', 'பெயர்ச்சொற்கள்', 'A naming word is a person, place or thing. Underline three in a sentence you write.', 'නම් පද', 'பெயர்ச்சொற்கள்', 'A naming word is a person, place or thing. Underline three in a sentence you write. Write one example in your own words before you leave the page.', 'නම් පද. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'பெயர்ச்சொற்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 2), (select id from subjects where grade_id = (select id from grades where number = 2) and slug = 'mathematics'), null, 'adding-up-to-100', 'Adding up to 100', '100 දක්වා එකතු කිරීම', '100 வரை கூட்டல்', 'Add the tens first, then the ones. 40 + 16 is 56.', '100 දක්වා එකතු කිරීම', '100 வரை கூட்டல்', 'Add the tens first, then the ones. 40 + 16 is 56. Write one example in your own words before you leave the page.', '100 දක්වා එකතු කිරීම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', '100 வரை கூட்டல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 2), (select id from subjects where grade_id = (select id from grades where number = 2) and slug = 'mathematics'), null, 'even-and-odd-numbers', 'Even and odd numbers', 'ඉරට්ටේ සහ ඔත්තේ', 'இரட்டை மற்றும் ஒற்றை', 'Even numbers pair up with nothing left over. Odd numbers always leave one out.', 'ඉරට්ටේ සහ ඔත්තේ', 'இரட்டை மற்றும் ஒற்றை', 'Even numbers pair up with nothing left over. Odd numbers always leave one out. Write one example in your own words before you leave the page.', 'ඉරට්ටේ සහ ඔත්තේ. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'இரட்டை மற்றும் ஒற்றை. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
