insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 2), (select id from subjects where grade_id = (select id from grades where number = 2) and slug = 'environment'), null, 'weather-today', 'Weather today', 'අද කාලගුණය', 'இன்றைய வானிலை', 'Weather is what the sky is doing now. Look outside and name the cloud, the wind and the light.', 'අද කාලගුණය', 'இன்றைய வானிலை', 'Weather is what the sky is doing now. Look outside and name the cloud, the wind and the light. Write one example in your own words before you leave the page.', 'අද කාලගුණය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'இன்றைய வானிலை. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 2), (select id from subjects where grade_id = (select id from grades where number = 2) and slug = 'english'), null, 'building-a-sentence', 'Building a sentence', 'වාක්‍යයක් සෑදීම', 'ஒரு வாக்கியம் அமைத்தல்', 'A sentence needs a naming part and a doing part, and it ends with a full stop.', 'වාක්‍යයක් සෑදීම', 'ஒரு வாக்கியம் அமைத்தல்', 'A sentence needs a naming part and a doing part, and it ends with a full stop. Write one example in your own words before you leave the page.', 'වාක්‍යයක් සෑදීම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'ஒரு வாக்கியம் அமைத்தல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 2), (select id from subjects where grade_id = (select id from grades where number = 2) and slug = 'english'), null, 'asking-questions', 'Asking questions', 'ප්‍රශ්න ඇසීම', 'கேள்விகள் கேட்டல்', 'Questions in English often start with who, what, where, when, why or how.', 'ප්‍රශ්න ඇසීම', 'கேள்விகள் கேட்டல்', 'Questions in English often start with who, what, where, when, why or how. Write one example in your own words before you leave the page.', 'ප්‍රශ්න ඇසීම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'கேள்விகள் கேட்டல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 3), (select id from subjects where grade_id = (select id from grades where number = 3) and slug = 'mathematics'), null, 'tables-of-2-5-and-10', 'Tables of 2, 5 and 10', '2, 5, 10 ගුණන වගු', '2, 5, 10 பெருக்கல்', 'Skip-count: 2, 4, 6 or 10, 20, 30. That is multiplication.', '2, 5, 10 ගුණන වගු', '2, 5, 10 பெருக்கல்', 'Skip-count: 2, 4, 6 or 10, 20, 30. That is multiplication. Write one example in your own words before you leave the page.', '2, 5, 10 ගුණන වගු. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', '2, 5, 10 பெருக்கல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 3), (select id from subjects where grade_id = (select id from grades where number = 3) and slug = 'mathematics'), null, 'clocks-and-half-hours', 'Clocks and half hours', 'ඔරලෝසුව සහ පැය භාගය', 'கடிகாரமும் அரை மணியும்', 'When the long hand is on 6, it is half past. Say the hour the short hand has passed.', 'ඔරලෝසුව සහ පැය භාගය', 'கடிகாரமும் அரை மணியும்', 'When the long hand is on 6, it is half past. Say the hour the short hand has passed. Write one example in your own words before you leave the page.', 'ඔරලෝසුව සහ පැය භාගය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'கடிகாரமும் அரை மணியும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 3), (select id from subjects where grade_id = (select id from grades where number = 3) and slug = 'environment'), null, 'habitats', 'Habitats', 'වාසස්ථාන', 'வாழ்விடங்கள்', 'A habitat is where a living thing finds food, water and shelter.', 'වාසස්ථාන', 'வாழ்விடங்கள்', 'A habitat is where a living thing finds food, water and shelter. Write one example in your own words before you leave the page.', 'වාසස්ථාන. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'வாழ்விடங்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 3), (select id from subjects where grade_id = (select id from grades where number = 3) and slug = 'environment'), null, 'reduce-and-reuse', 'Reduce and reuse', 'අඩු කරන්න, නැවත යොදාගන්න', 'குறைத்தல் மற்றும் மறுபயன்பாடு', 'Reducing means not taking it in the first place. Reusing means a second job for the same object.', 'අඩු කරන්න, නැවත යොදාගන්න', 'குறைத்தல் மற்றும் மறுபயன்பாடு', 'Reducing means not taking it in the first place. Reusing means a second job for the same object. Write one example in your own words before you leave the page.', 'අඩු කරන්න, නැවත යොදාගන්න. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'குறைத்தல் மற்றும் மறுபயன்பாடு. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 3), (select id from subjects where grade_id = (select id from grades where number = 3) and slug = 'english'), null, 'the-order-of-a-story', 'The order of a story', 'කතාවේ පිළිවෙල', 'கதையின் வரிசை', 'Tell what happened first, next and last. If you mix the order, the story breaks.', 'කතාවේ පිළිවෙල', 'கதையின் வரிசை', 'Tell what happened first, next and last. If you mix the order, the story breaks. Write one example in your own words before you leave the page.', 'කතාවේ පිළිවෙල. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'கதையின் வரிசை. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 3), (select id from subjects where grade_id = (select id from grades where number = 3) and slug = 'english'), null, 'describing-words', 'Describing words', 'විස්තර පද', 'விளக்கச் சொற்கள்', 'A describing word tells us more about a naming word: a red bag, a quiet room.', 'විස්තර පද', 'விளக்கச் சொற்கள்', 'A describing word tells us more about a naming word: a red bag, a quiet room. Write one example in your own words before you leave the page.', 'විස්තර පද. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'விளக்கச் சொற்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 4), (select id from subjects where grade_id = (select id from grades where number = 4) and slug = 'mathematics'), null, 'fractions-as-equal-parts', 'Fractions as equal parts', 'සම කොටස් ලෙස භාග', 'சம பாகங்களாக பின்னங்கள்', 'A half is one of two equal parts. Equal means the same size, not just two pieces.', 'සම කොටස් ලෙස භාග', 'சம பாகங்களாக பின்னங்கள்', 'A half is one of two equal parts. Equal means the same size, not just two pieces. Write one example in your own words before you leave the page.', 'සම කොටස් ලෙස භාග. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'சம பாகங்களாக பின்னங்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 4), (select id from subjects where grade_id = (select id from grades where number = 4) and slug = 'mathematics'), null, 'measuring-length', 'Measuring length', 'දිග මැනීම', 'நீளத்தை அளத்தல்', 'Line the zero up with the end of the object. Read the mark at the other end.', 'දිග මැනීම', 'நீளத்தை அளத்தல்', 'Line the zero up with the end of the object. Read the mark at the other end. Write one example in your own words before you leave the page.', 'දිග මැනීම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'நீளத்தை அளத்தல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 4), (select id from subjects where grade_id = (select id from grades where number = 4) and slug = 'environment'), null, 'food-chains', 'Food chains', 'ආහාර දාම', 'உணவுச் சங்கிலி', 'Energy moves from the plant, to the eater, to the next eater. The arrows point at who eats.', 'ආහාර දාම', 'உணவுச் சங்கிலி', 'Energy moves from the plant, to the eater, to the next eater. The arrows point at who eats. Write one example in your own words before you leave the page.', 'ආහාර දාම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'உணவுச் சங்கிலி. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 4), (select id from subjects where grade_id = (select id from grades where number = 4) and slug = 'environment'), null, 'soil-and-roots', 'Soil and roots', 'පස සහ මුල්', 'மண்ணும் வேர்களும்', 'Roots hold the plant and take in water. Soil is where that water is stored.', 'පස සහ මුල්', 'மண்ணும் வேர்களும்', 'Roots hold the plant and take in water. Soil is where that water is stored. Write one example in your own words before you leave the page.', 'පස සහ මුල්. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'மண்ணும் வேர்களும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 4), (select id from subjects where grade_id = (select id from grades where number = 4) and slug = 'english'), null, 'writing-a-paragraph', 'Writing a paragraph', 'ඡේදයක් ලිවීම', 'ஒரு பத்தி எழுதுதல்', 'A paragraph is one idea. The first sentence says it. The next sentences explain it.', 'ඡේදයක් ලිවීම', 'ஒரு பத்தி எழுதுதல்', 'A paragraph is one idea. The first sentence says it. The next sentences explain it. Write one example in your own words before you leave the page.', 'ඡේදයක් ලිවීම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'ஒரு பத்தி எழுதுதல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 4), (select id from subjects where grade_id = (select id from grades where number = 4) and slug = 'english'), null, 'stories-in-the-past', 'Stories in the past', 'අතීත කාල කතා', 'இறந்த காலக் கதைகள்', 'Past tense tells us it already happened. Walk becomes walked. Go becomes went.', 'අතීත කාල කතා', 'இறந்த காலக் கதைகள்', 'Past tense tells us it already happened. Walk becomes walked. Go becomes went. Write one example in your own words before you leave the page.', 'අතීත කාල කතා. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'இறந்த காலக் கதைகள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 5), (select id from subjects where grade_id = (select id from grades where number = 5) and slug = 'mathematics'), null, 'decimals-to-tenths', 'Decimals to tenths', 'දශමස්ථාන දක්වා', 'தசமங்கள்', '0.1 is one tenth. Ten tenths make one whole.', 'දශමස්ථාන දක්වා', 'தசமங்கள்', '0.1 is one tenth. Ten tenths make one whole. Write one example in your own words before you leave the page.', 'දශමස්ථාන දක්වා. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'தசமங்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 5), (select id from subjects where grade_id = (select id from grades where number = 5) and slug = 'mathematics'), null, 'area-of-a-rectangle', 'Area of a rectangle', 'ඍජුකෝණාස්‍රයේ වර්ගඵලය', 'செவ்வகத்தின் பரப்பளவு', 'Area is length times width. A 4 by 3 rectangle covers 12 squares.', 'ඍජුකෝණාස්‍රයේ වර්ගඵලය', 'செவ்வகத்தின் பரப்பளவு', 'Area is length times width. A 4 by 3 rectangle covers 12 squares. Write one example in your own words before you leave the page.', 'ඍජුකෝණාස්‍රයේ වර්ගඵලය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'செவ்வகத்தின் பரப்பளவு. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 5), (select id from subjects where grade_id = (select id from grades where number = 5) and slug = 'environment'), null, 'human-body-systems', 'Human body systems', 'මිනිස් සිරුරේ පද්ධති', 'மனித உடல் அமைப்புகள்', 'The body is teams of organs. Breathing, moving and digesting are three different teams.', 'මිනිස් සිරුරේ පද්ධති', 'மனித உடல் அமைப்புகள்', 'The body is teams of organs. Breathing, moving and digesting are three different teams. Write one example in your own words before you leave the page.', 'මිනිස් සිරුරේ පද්ධති. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'மனித உடல் அமைப்புகள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 5), (select id from subjects where grade_id = (select id from grades where number = 5) and slug = 'environment'), null, 'energy-at-home', 'Energy at home', 'නිවසේ ශක්තිය', 'வீட்டில் ஆற்றல்', 'Lamps, fans and cooking all use energy. Switching off what you are not using is part of the lesson.', 'නිවසේ ශක්තිය', 'வீட்டில் ஆற்றல்', 'Lamps, fans and cooking all use energy. Switching off what you are not using is part of the lesson. Write one example in your own words before you leave the page.', 'නිවසේ ශක්තිය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'வீட்டில் ஆற்றல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 5), (select id from subjects where grade_id = (select id from grades where number = 5) and slug = 'english'), null, 'writing-a-summary', 'Writing a summary', 'සාරාංශයක් ලිවීම', 'ஒரு சுருக்கம் எழுதுதல்', 'A summary keeps the main idea and drops the examples. Aim for three sentences.', 'සාරාංශයක් ලිවීම', 'ஒரு சுருக்கம் எழுதுதல்', 'A summary keeps the main idea and drops the examples. Aim for three sentences. Write one example in your own words before you leave the page.', 'සාරාංශයක් ලිවීම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'ஒரு சுருக்கம் எழுதுதல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 5), (select id from subjects where grade_id = (select id from grades where number = 5) and slug = 'english'), null, 'formal-and-informal-english', 'Formal and informal English', 'විධිමත් සහ අවිධිමත්', 'முறையான மற்றும் சாதாரண ஆங்கிலம்', 'You write to a teacher more formally than you talk to a friend. Both are correct in their place.', 'විධිමත් සහ අවිධිමත්', 'முறையான மற்றும் சாதாரண ஆங்கிலம்', 'You write to a teacher more formally than you talk to a friend. Both are correct in their place. Write one example in your own words before you leave the page.', 'විධිමත් සහ අවිධිමත්. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'முறையான மற்றும் சாதாரண ஆங்கிலம். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 6), (select id from subjects where grade_id = (select id from grades where number = 6) and slug = 'mathematics'), null, 'whole-numbers-and-integers', 'Whole numbers and integers', 'පූර්ණ සංඛ්‍යා', 'முழு எண்கள்', 'Integers continue below zero. Negative means the opposite direction.', 'පූර්ණ සංඛ්‍යා', 'முழு எண்கள்', 'Integers continue below zero. Negative means the opposite direction. Write one example in your own words before you leave the page.', 'පූර්ණ සංඛ්‍යා. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'முழு எண்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 6), (select id from subjects where grade_id = (select id from grades where number = 6) and slug = 'mathematics'), null, 'ratio-in-a-recipe', 'Ratio in a recipe', 'වට්ටෝරුවක අනුපාතය', 'சமையலில் விகிதம்', 'A 1 to 2 ratio means for every 1 cup of rice, use 2 cups of water.', 'වට්ටෝරුවක අනුපාතය', 'சமையலில் விகிதம்', 'A 1 to 2 ratio means for every 1 cup of rice, use 2 cups of water. Write one example in your own words before you leave the page.', 'වට්ටෝරුවක අනුපාතය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'சமையலில் விகிதம். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 6), (select id from subjects where grade_id = (select id from grades where number = 6) and slug = 'science'), (select id from videos where youtube_id = 'XOdK3De8f60'), 'plant-and-animal-cells', 'Plant and animal cells', 'ශාක හා සත්ව සෛල', 'தாவர மற்றும் விலங்கு செல்கள்', 'Both have a membrane, cytoplasm and a nucleus. Only plant cells have a cell wall and chloroplasts.', 'ශාක හා සත්ව සෛල', 'தாவர மற்றும் விலங்கு செல்கள்', 'Both have a membrane, cytoplasm and a nucleus. Only plant cells have a cell wall and chloroplasts. Write one example in your own words before you leave the page.', 'ශාක හා සත්ව සෛල. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'தாவர மற்றும் விலங்கு செல்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, true);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 6), (select id from subjects where grade_id = (select id from grades where number = 6) and slug = 'science'), (select id from videos where youtube_id = 'sK3liWW_pEk'), 'animal-cells-up-close', 'Animal cells up close', 'සත්ව සෛල ළඟින්', 'விலங்கு செல்கள் அருகில்', 'Animal cells have no cell wall. The membrane is the outer boundary, and the nucleus sits in the cytoplasm.', 'සත්ව සෛල ළඟින්', 'விலங்கு செல்கள் அருகில்', 'Animal cells have no cell wall. The membrane is the outer boundary, and the nucleus sits in the cytoplasm. Write one example in your own words before you leave the page.', 'සත්ව සෛල ළඟින්. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'விலங்கு செல்கள் அருகில். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 6), (select id from subjects where grade_id = (select id from grades where number = 6) and slug = 'history'), null, 'reading-a-timeline', 'Reading a timeline', 'කාල රේඛාවක් කියවීම', 'ஒரு காலக்கோட்டை வாசித்தல்', 'A timeline puts events in order. Earlier is to the left. The gap shows how long between events.', 'කාල රේඛාවක් කියවීම', 'ஒரு காலக்கோட்டை வாசித்தல்', 'A timeline puts events in order. Earlier is to the left. The gap shows how long between events. Write one example in your own words before you leave the page.', 'කාල රේඛාවක් කියවීම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'ஒரு காலக்கோட்டை வாசித்தல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 6), (select id from subjects where grade_id = (select id from grades where number = 6) and slug = 'history'), null, 'history-in-a-family', 'History in a family', 'පවුලක ඉතිහාසය', 'ஒரு குடும்பத்தின் வரலாறு', 'Ask an older person for one story and one date. Oral history is still evidence. Write who told you.', 'පවුලක ඉතිහාසය', 'ஒரு குடும்பத்தின் வரலாறு', 'Ask an older person for one story and one date. Oral history is still evidence. Write who told you. Write one example in your own words before you leave the page.', 'පවුලක ඉතිහාසය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'ஒரு குடும்பத்தின் வரலாறு. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 7), (select id from subjects where grade_id = (select id from grades where number = 7) and slug = 'mathematics'), null, 'expressions-and-brackets', 'Expressions and brackets', 'ප්‍රකාශන සහ වරහන්', 'கோவைகளும் அடைப்புக்குறிகளும்', 'Do the brackets first. 2 × (3 + 4) is 14, not 10.', 'ප්‍රකාශන සහ වරහන්', 'கோவைகளும் அடைப்புக்குறிகளும்', 'Do the brackets first. 2 × (3 + 4) is 14, not 10. Write one example in your own words before you leave the page.', 'ප්‍රකාශන සහ වරහන්. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'கோவைகளும் அடைப்புக்குறிகளும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 7), (select id from subjects where grade_id = (select id from grades where number = 7) and slug = 'mathematics'), null, 'angles-in-a-triangle', 'Angles in a triangle', 'ත්‍රිකෝණයේ කෝණ', 'முக்கோணத்தின் கோணங்கள்', 'The three inside angles of any triangle add up to 180 degrees.', 'ත්‍රිකෝණයේ කෝණ', 'முக்கோணத்தின் கோணங்கள்', 'The three inside angles of any triangle add up to 180 degrees. Write one example in your own words before you leave the page.', 'ත්‍රිකෝණයේ කෝණ. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'முக்கோணத்தின் கோணங்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 7), (select id from subjects where grade_id = (select id from grades where number = 7) and slug = 'science'), null, 'forces-and-motion', 'Forces and motion', 'බල සහ චලිතය', 'விசையும் இயக்கமும்', 'A force is a push or a pull. It can start, stop or change the direction of motion.', 'බල සහ චලිතය', 'விசையும் இயக்கமும்', 'A force is a push or a pull. It can start, stop or change the direction of motion. Write one example in your own words before you leave the page.', 'බල සහ චලිතය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'விசையும் இயக்கமும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 7), (select id from subjects where grade_id = (select id from grades where number = 7) and slug = 'science'), null, 'the-digestive-system', 'The digestive system', 'ජීර්ණ පද්ධතිය', 'செரிமான அமைப்பு', 'Food is broken down so the body can use it. The path runs from mouth to stomach to intestine.', 'ජීර්ණ පද්ධතිය', 'செரிமான அமைப்பு', 'Food is broken down so the body can use it. The path runs from mouth to stomach to intestine. Write one example in your own words before you leave the page.', 'ජීර්ණ පද්ධතිය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'செரிமான அமைப்பு. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
