insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 7), (select id from subjects where grade_id = (select id from grades where number = 7) and slug = 'history'), null, 'maps-as-evidence', 'Maps as evidence', 'සාක්ෂි ලෙස සිතියම්', 'சான்றாக வரைபடங்கள்', 'A map is an argument about a place. Check who drew it and what they left out.', 'සාක්ෂි ලෙස සිතියම්', 'சான்றாக வரைபடங்கள்', 'A map is an argument about a place. Check who drew it and what they left out. Write one example in your own words before you leave the page.', 'සාක්ෂි ලෙස සිතියම්. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'சான்றாக வரைபடங்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 8), (select id from subjects where grade_id = (select id from grades where number = 8) and slug = 'mathematics'), (select id from videos where youtube_id = 'plZV63uofgs'), 'pythagoras-theorem', 'Pythagoras theorem', 'පයිතගරස් ප්‍රමේයය', 'பித்தாகரஸ் தேற்றம்', 'On a right triangle, a² + b² = c². The hypotenuse is the side opposite the right angle.', 'පයිතගරස් ප්‍රමේයය', 'பித்தாகரஸ் தேற்றம்', 'On a right triangle, a² + b² = c². The hypotenuse is the side opposite the right angle. Write one example in your own words before you leave the page.', 'පයිතගරස් ප්‍රමේයය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'பித்தாகரஸ் தேற்றம். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, true);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 8), (select id from subjects where grade_id = (select id from grades where number = 8) and slug = 'mathematics'), null, 'linear-equations', 'Linear equations', 'රේඛීය සමීකරණ', 'நேரியல் சமன்பாடுகள்', 'Keep the equation balanced. Whatever you do to one side, do to the other.', 'රේඛීය සමීකරණ', 'நேரியல் சமன்பாடுகள்', 'Keep the equation balanced. Whatever you do to one side, do to the other. Write one example in your own words before you leave the page.', 'රේඛීය සමීකරණ. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'நேரியல் சமன்பாடுகள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 8), (select id from subjects where grade_id = (select id from grades where number = 8) and slug = 'science'), null, 'chemical-changes', 'Chemical changes', 'රසායනික වෙනස්වීම්', 'வேதியியல் மாற்றங்கள்', 'A chemical change makes a new substance. Burning wood is not the same as cutting it.', 'රසායනික වෙනස්වීම්', 'வேதியியல் மாற்றங்கள்', 'A chemical change makes a new substance. Burning wood is not the same as cutting it. Write one example in your own words before you leave the page.', 'රසායනික වෙනස්වීම්. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'வேதியியல் மாற்றங்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 8), (select id from subjects where grade_id = (select id from grades where number = 8) and slug = 'science'), null, 'simple-circuits', 'Simple circuits', 'සරල පරිපථ', 'எளிய மின்சுற்றுகள்', 'A circuit needs a full loop: cell, wires and lamp. A gap stops the current.', 'සරල පරිපථ', 'எளிய மின்சுற்றுகள்', 'A circuit needs a full loop: cell, wires and lamp. A gap stops the current. Write one example in your own words before you leave the page.', 'සරල පරිපථ. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'எளிய மின்சுற்றுகள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 8), (select id from subjects where grade_id = (select id from grades where number = 8) and slug = 'history'), (select id from videos where youtube_id = '8e93m-3AU4E'), 'pythagoras-and-the-ancient-world', 'Pythagoras and the ancient world', 'පයිතගරස් සහ පුරාණ ලෝකය', 'பித்தாகரசும் பண்டைய உலகும்', 'Pythagoras lived on Samos around 570 BCE. His name survived because the idea was useful, not because he was a king.', 'පයිතගරස් සහ පුරාණ ලෝකය', 'பித்தாகரசும் பண்டைய உலகும்', 'Pythagoras lived on Samos around 570 BCE. His name survived because the idea was useful, not because he was a king. Write one example in your own words before you leave the page.', 'පයිතගරස් සහ පුරාණ ලෝකය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'பித்தாகரசும் பண்டைய உலகும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 8), (select id from subjects where grade_id = (select id from grades where number = 8) and slug = 'history'), null, 'kingdoms-of-sri-lanka', 'Kingdoms of Sri Lanka', 'ශ්‍රී ලංකාවේ රාජධානි', 'இலங்கையின் அரசுகள்', 'Tanks, stupas and inscriptions are evidence you can still visit. A kingdom is more than a list of kings.', 'ශ්‍රී ලංකාවේ රාජධානි', 'இலங்கையின் அரசுகள்', 'Tanks, stupas and inscriptions are evidence you can still visit. A kingdom is more than a list of kings. Write one example in your own words before you leave the page.', 'ශ්‍රී ලංකාවේ රාජධානි. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'இலங்கையின் அரசுகள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 9), (select id from subjects where grade_id = (select id from grades where number = 9) and slug = 'mathematics'), null, 'indices-and-powers', 'Indices and powers', 'දර්ශක', 'அடுக்குக்குறிகள்', '2 to the power 3 means 2 × 2 × 2, which is 8. The index counts the factors.', 'දර්ශක', 'அடுக்குக்குறிகள்', '2 to the power 3 means 2 × 2 × 2, which is 8. The index counts the factors. Write one example in your own words before you leave the page.', 'දර්ශක. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'அடுக்குக்குறிகள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 9), (select id from subjects where grade_id = (select id from grades where number = 9) and slug = 'mathematics'), null, 'probability-with-a-die', 'Probability with a die', 'දාදුවක සම්භාවිතාව', 'பகடையும் நிகழ்தகவும்', 'A fair die has 6 faces. The chance of a 4 is 1 out of 6.', 'දාදුවක සම්භාවිතාව', 'பகடையும் நிகழ்தகவும்', 'A fair die has 6 faces. The chance of a 4 is 1 out of 6. Write one example in your own words before you leave the page.', 'දාදුවක සම්භාවිතාව. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'பகடையும் நிகழ்தகவும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 9), (select id from subjects where grade_id = (select id from grades where number = 9) and slug = 'science'), null, 'waves-and-sound', 'Waves and sound', 'තරංග සහ ශබ්දය', 'அலைகளும் ஒலியும்', 'Sound is a vibration travelling through something. No air, no sound, which is why space is silent.', 'තරංග සහ ශබ්දය', 'அலைகளும் ஒலியும்', 'Sound is a vibration travelling through something. No air, no sound, which is why space is silent. Write one example in your own words before you leave the page.', 'තරංග සහ ශබ්දය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'அலைகளும் ஒலியும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 9), (select id from subjects where grade_id = (select id from grades where number = 9) and slug = 'science'), null, 'ecosystems', 'Ecosystems', 'පරිසර පද්ධති', 'சுற்றுச்சூழல் அமைப்புகள்', 'An ecosystem is the living things plus the place they share. Change one part and the others feel it.', 'පරිසර පද්ධති', 'சுற்றுச்சூழல் அமைப்புகள்', 'An ecosystem is the living things plus the place they share. Change one part and the others feel it. Write one example in your own words before you leave the page.', 'පරිසර පද්ධති. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'சுற்றுச்சூழல் அமைப்புகள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 9), (select id from subjects where grade_id = (select id from grades where number = 9) and slug = 'history'), null, 'the-world-at-war', 'The world at war', 'යුද්ධයේ ලෝකය', 'போரில் உலகம்', 'A world war pulls in countries that are not the first to fight. Follow one country''s path, not every battle.', 'යුද්ධයේ ලෝකය', 'போரில் உலகம்', 'A world war pulls in countries that are not the first to fight. Follow one country''s path, not every battle. Write one example in your own words before you leave the page.', 'යුද්ධයේ ලෝකය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'போரில் உலகம். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 9), (select id from subjects where grade_id = (select id from grades where number = 9) and slug = 'history'), null, 'independence-movements', 'Independence movements', 'නිදහස් අරගල', 'விடுதலை இயக்கங்கள்', 'Independence is a political change and a daily one. Ask what changed for ordinary people, not only for leaders.', 'නිදහස් අරගල', 'விடுதலை இயக்கங்கள்', 'Independence is a political change and a daily one. Ask what changed for ordinary people, not only for leaders. Write one example in your own words before you leave the page.', 'නිදහස් අරගල. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'விடுதலை இயக்கங்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 10), (select id from subjects where grade_id = (select id from grades where number = 10) and slug = 'mathematics'), null, 'equations-and-formulae', 'Equations and formulae', 'සමීකරණ සහ සූත්‍ර', 'சமன்பாடுகளும் வாய்ப்பாடுகளும்', 'A formula is a rule you can substitute into. Write the units beside the numbers.', 'සමීකරණ සහ සූත්‍ර', 'சமன்பாடுகளும் வாய்ப்பாடுகளும்', 'A formula is a rule you can substitute into. Write the units beside the numbers. Write one example in your own words before you leave the page.', 'සමීකරණ සහ සූත්‍ර. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'சமன்பாடுகளும் வாய்ப்பாடுகளும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 10), (select id from subjects where grade_id = (select id from grades where number = 10) and slug = 'mathematics'), null, 'right-triangle-trigonometry', 'Right-triangle trigonometry', 'සෘජුකෝණී ත්‍රිකෝණමිතිය', 'செங்கோண முக்கோணம்', 'Sine, cosine and tangent compare two sides of a right triangle.', 'සෘජුකෝණී ත්‍රිකෝණමිතිය', 'செங்கோண முக்கோணம்', 'Sine, cosine and tangent compare two sides of a right triangle. Write one example in your own words before you leave the page.', 'සෘජුකෝණී ත්‍රිකෝණමිතිය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'செங்கோண முக்கோணம். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 10), (select id from subjects where grade_id = (select id from grades where number = 10) and slug = 'science'), (select id from videos where youtube_id = 'aoCBKqae3r8'), 'cells-in-detail', 'Cells in detail', 'සෛල විස්තරාත්මකව', 'செல்கள் விரிவாக', 'Organelles are the parts inside a cell. The nucleus holds the instructions. Mitochondria release energy.', 'සෛල විස්තරාත්මකව', 'செல்கள் விரிவாக', 'Organelles are the parts inside a cell. The nucleus holds the instructions. Mitochondria release energy. Write one example in your own words before you leave the page.', 'සෛල විස්තරාත්මකව. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'செல்கள் விரிவாக. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, true);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 10), (select id from subjects where grade_id = (select id from grades where number = 10) and slug = 'science'), null, 'chemical-basis-of-life', 'Chemical basis of life', 'ජීවයේ රසායනික පදනම', 'வாழ்க்கையின் வேதியியல் அடிப்படை', 'Living things are built from a small set of elements. Carbon is in every one of those large molecules.', 'ජීවයේ රසායනික පදනම', 'வாழ்க்கையின் வேதியியல் அடிப்படை', 'Living things are built from a small set of elements. Carbon is in every one of those large molecules. Write one example in your own words before you leave the page.', 'ජීවයේ රසායනික පදනම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'வாழ்க்கையின் வேதியியல் அடிப்படை. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 10), (select id from subjects where grade_id = (select id from grades where number = 10) and slug = 'ict'), null, 'what-a-computer-is', 'What a computer is', 'පරිගණකයක් යනු කුමක්ද', 'கணினி என்றால் என்ன', 'Input, processing, storage and output. A phone is a computer you can hold.', 'පරිගණකයක් යනු කුමක්ද', 'கணினி என்றால் என்ன', 'Input, processing, storage and output. A phone is a computer you can hold. Write one example in your own words before you leave the page.', 'පරිගණකයක් යනු කුමක්ද. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'கணினி என்றால் என்ன. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
