insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 11), (select id from subjects where grade_id = (select id from grades where number = 11) and slug = 'mathematics'), null, 'facts-about-circles', 'Facts about circles', 'වෘත්තය පිළිබඳ කරුණු', 'வட்டம் பற்றிய உண்மைகள்', 'The diameter is twice the radius. All radii of one circle are the same length.', 'වෘත්තය පිළිබඳ කරුණු', 'வட்டம் பற்றிய உண்மைகள்', 'The diameter is twice the radius. All radii of one circle are the same length. Write one example in your own words before you leave the page.', 'වෘත්තය පිළිබඳ කරුණු. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'வட்டம் பற்றிய உண்மைகள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 11), (select id from subjects where grade_id = (select id from grades where number = 11) and slug = 'science'), null, 'light-and-lenses', 'Light and lenses', 'ආලෝකය සහ කාච', 'ஒளியும் வில்லைகளும்', 'A lens bends light. A convex lens can bring rays together to a point.', 'ආලෝකය සහ කාච', 'ஒளியும் வில்லைகளும்', 'A lens bends light. A convex lens can bring rays together to a point. Write one example in your own words before you leave the page.', 'ආලෝකය සහ කාච. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'ஒளியும் வில்லைகளும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 11), (select id from subjects where grade_id = (select id from grades where number = 11) and slug = 'science'), null, 'reactions-and-rates', 'Reactions and rates', 'ප්‍රතික්‍රියා සහ වේග', 'வினைகளும் வேகமும்', 'Heat, concentration and surface area change how fast a reaction goes. They do not change what is made.', 'ප්‍රතික්‍රියා සහ වේග', 'வினைகளும் வேகமும்', 'Heat, concentration and surface area change how fast a reaction goes. They do not change what is made. Write one example in your own words before you leave the page.', 'ප්‍රතික්‍රියා සහ වේග. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'வினைகளும் வேகமும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 11), (select id from subjects where grade_id = (select id from grades where number = 11) and slug = 'ict'), null, 'spreadsheets', 'Spreadsheets', 'පැතුරුම්පත්', 'விரிதாள்கள்', 'A cell is a row and a column. A formula starts with = and updates when the numbers change.', 'පැතුරුම්පත්', 'விரிதாள்கள்', 'A cell is a row and a column. A formula starts with = and updates when the numbers change. Write one example in your own words before you leave the page.', 'පැතුරුම්පත්. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'விரிதாள்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 11), (select id from subjects where grade_id = (select id from grades where number = 11) and slug = 'ict'), null, 'how-the-internet-moves-data', 'How the internet moves data', 'අන්තර්ජාලය දත්ත ගෙනයන හැටි', 'இணையம் தரவை நகர்த்தும் விதம்', 'A message is split into packets. Each packet can take its own road and they meet again at the end.', 'අන්තර්ජාලය දත්ත ගෙනයන හැටි', 'இணையம் தரவை நகர்த்தும் விதம்', 'A message is split into packets. Each packet can take its own road and they meet again at the end. Write one example in your own words before you leave the page.', 'අන්තර්ජාලය දත්ත ගෙනයන හැටි. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'இணையம் தரவை நகர்த்தும் விதம். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 12), (select id from subjects where grade_id = (select id from grades where number = 12) and slug = 'combined-maths'), null, 'rates-of-change', 'Rates of change', 'වෙනස්වීමේ අනුපාත', 'மாற்ற விகிதம்', 'A rate compares a change to the time it took. Speed is distance over time.', 'වෙනස්වීමේ අනුපාත', 'மாற்ற விகிதம்', 'A rate compares a change to the time it took. Speed is distance over time. Write one example in your own words before you leave the page.', 'වෙනස්වීමේ අනුපාත. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'மாற்ற விகிதம். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 12), (select id from subjects where grade_id = (select id from grades where number = 12) and slug = 'combined-maths'), null, 'vectors-in-the-plane', 'Vectors in the plane', 'තලයේ දෛශික', 'தளத்தில் திசையன்கள்', 'A vector has size and direction. Adding vectors is tip-to-tail.', 'තලයේ දෛශික', 'தளத்தில் திசையன்கள்', 'A vector has size and direction. Adding vectors is tip-to-tail. Write one example in your own words before you leave the page.', 'තලයේ දෛශික. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'தளத்தில் திசையன்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 12), (select id from subjects where grade_id = (select id from grades where number = 12) and slug = 'physics'), null, 'units-and-vectors', 'Units and vectors', 'ඒකක සහ දෛශික', 'அலகுகளும் திசையன்களும்', 'A number without a unit is not a measurement. A vector also needs a direction.', 'ඒකක සහ දෛශික', 'அலகுகளும் திசையன்களும்', 'A number without a unit is not a measurement. A vector also needs a direction. Write one example in your own words before you leave the page.', 'ඒකක සහ දෛශික. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'அலகுகளும் திசையன்களும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 12), (select id from subjects where grade_id = (select id from grades where number = 12) and slug = 'physics'), null, 'motion-in-a-straight-line', 'Motion in a straight line', 'සරල රේඛීය චලිතය', 'நேர்க்கோட்டு இயக்கம்', 'Displacement is the change in position. Distance is how much ground you covered. They are not the same.', 'සරල රේඛීය චලිතය', 'நேர்க்கோட்டு இயக்கம்', 'Displacement is the change in position. Distance is how much ground you covered. They are not the same. Write one example in your own words before you leave the page.', 'සරල රේඛීය චලිතය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'நேர்க்கோட்டு இயக்கம். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 12), (select id from subjects where grade_id = (select id from grades where number = 12) and slug = 'biology'), (select id from videos where youtube_id = 'YY5ciDx7Y3Q'), 'a-review-of-the-cell', 'A review of the cell', 'සෛලය නැවත බැලීම', 'செல்லை மீண்டும் பார்த்தல்', 'Before A/L detail, be able to point to membrane, cytoplasm and nucleus and say what each does.', 'සෛලය නැවත බැලීම', 'செல்லை மீண்டும் பார்த்தல்', 'Before A/L detail, be able to point to membrane, cytoplasm and nucleus and say what each does. Write one example in your own words before you leave the page.', 'සෛලය නැවත බැලීම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'செல்லை மீண்டும் பார்த்தல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 12), (select id from subjects where grade_id = (select id from grades where number = 12) and slug = 'biology'), null, 'genetics-in-one-page', 'Genetics in one page', 'ජාන විද්‍යාව කෙටියෙන්', 'மரபியல் ஒரே பக்கத்தில்', 'A gene is a stretch of instruction. You have two copies of most genes, one from each parent.', 'ජාන විද්‍යාව කෙටියෙන්', 'மரபியல் ஒரே பக்கத்தில்', 'A gene is a stretch of instruction. You have two copies of most genes, one from each parent. Write one example in your own words before you leave the page.', 'ජාන විද්‍යාව කෙටියෙන්. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'மரபியல் ஒரே பக்கத்தில். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 13), (select id from subjects where grade_id = (select id from grades where number = 13) and slug = 'combined-maths'), null, 'integration-as-area', 'Integration as area', 'වර්ගඵලය ලෙස අනුකලනය', 'பரப்பளவாகத் தொகையீடு', 'The area under a speed-time graph is the distance travelled.', 'වර්ගඵලය ලෙස අනුකලනය', 'பரப்பளவாகத் தொகையீடு', 'The area under a speed-time graph is the distance travelled. Write one example in your own words before you leave the page.', 'වර්ගඵලය ලෙස අනුකලනය. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'பரப்பளவாகத் தொகையீடு. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 13), (select id from subjects where grade_id = (select id from grades where number = 13) and slug = 'combined-maths'), null, 'binomial-ideas', 'Binomial ideas', 'ද්විපද අදහස්', 'ஈருறுப்பு எண்ணங்கள்', '(a + b)² = a² + 2ab + b². The middle term is easy to forget, so write it first.', 'ද්විපද අදහස්', 'ஈருறுப்பு எண்ணங்கள்', '(a + b)² = a² + 2ab + b². The middle term is easy to forget, so write it first. Write one example in your own words before you leave the page.', 'ද්විපද අදහස්. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'ஈருறுப்பு எண்ணங்கள். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 13), (select id from subjects where grade_id = (select id from grades where number = 13) and slug = 'physics'), null, 'forces-and-newton', 'Forces and Newton', 'බල සහ නිව්ටන්', 'விசைகளும் நியூட்டனும்', 'If the forces on an object cancel, it does not accelerate. Newton''s laws are about that balance.', 'බල සහ නිව්ටන්', 'விசைகளும் நியூட்டனும்', 'If the forces on an object cancel, it does not accelerate. Newton''s laws are about that balance. Write one example in your own words before you leave the page.', 'බල සහ නිව්ටන්. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'விசைகளும் நியூட்டனும். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 13), (select id from subjects where grade_id = (select id from grades where number = 13) and slug = 'physics'), null, 'waves-an-introduction', 'Waves, an introduction', 'තරංග හැඳින්වීම', 'அலைகள்: ஒரு அறிமுகம்', 'A wave carries energy without carrying the material along. Water moves up and down. The wave moves forward.', 'තරංග හැඳින්වීම', 'அலைகள்: ஒரு அறிமுகம்', 'A wave carries energy without carrying the material along. Water moves up and down. The wave moves forward. Write one example in your own words before you leave the page.', 'තරංග හැඳින්වීම. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'அலைகள்: ஒரு அறிமுகம். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 13), (select id from subjects where grade_id = (select id from grades where number = 13) and slug = 'biology'), null, 'human-physiology', 'Human physiology', 'මිනිස් කායික විද්‍යාව', 'மனித உடலியல்', 'Physiology asks how the part works, not only what it is called. Follow one system from input to output.', 'මිනිස් කායික විද්‍යාව', 'மனித உடலியல்', 'Physiology asks how the part works, not only what it is called. Follow one system from input to output. Write one example in your own words before you leave the page.', 'මිනිස් කායික විද්‍යාව. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'மனித உடலியல். படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'free', 'published', 1, false);
insert into lessons (grade_id, subject_id, video_id, slug, title_en, title_si, title_ta, summary_en, summary_si, summary_ta, notes_en, notes_si, notes_ta, tier_required, status, sort_order, is_featured) values ((select id from grades where number = 13), (select id from subjects where grade_id = (select id from grades where number = 13) and slug = 'biology'), null, 'evidence-for-evolution', 'Evidence for evolution', 'පරිණාමයට සාක්ෂි', 'பரிணாமத்துக்கான சான்று', 'Fossils, shared body plans and DNA tell the same story from three different desks.', 'පරිණාමයට සාක්ෂි', 'பரிணாமத்துக்கான சான்று', 'Fossils, shared body plans and DNA tell the same story from three different desks. Write one example in your own words before you leave the page.', 'පරිණාමයට සාක්ෂි. පියවරෙන් පියවර ලියා, අන්තිමේ පිළිතුර පරීක්ෂා කරන්න.', 'பரிணாமத்துக்கான சான்று. படிப்படியாக எழுதி, இறுதியில் விடையைச் சரிபாருங்கள்.', 'premium', 'published', 2, false);
