insert into quiz_questions (quiz_id, prompt_en, prompt_si, prompt_ta, choices_en, choices_si, choices_ta, correct_index, sort_order) values ((select id from quizzes where lesson_id = (select id from lessons where slug = 'counting-to-20')), 'What is 8 + 7?', '8 + 7 කීයද?', '8 + 7 எவ்வளவு?', '["14","15","16","13"]', '["14","15","16","13"]', '["14","15","16","13"]', 1, 1);
insert into quiz_questions (quiz_id, prompt_en, prompt_si, prompt_ta, choices_en, choices_si, choices_ta, correct_index, sort_order) values ((select id from quizzes where lesson_id = (select id from lessons where slug = 'counting-to-20')), 'Which number comes right after 19?', '19 ට පසු ඊළඟ අංකය කුමක්ද?', '19 க்கு அடுத்து வரும் எண் எது?', '["18","20","21","17"]', '["18","20","21","17"]', '["18","20","21","17"]', 1, 2);
insert into quiz_questions (quiz_id, prompt_en, prompt_si, prompt_ta, choices_en, choices_si, choices_ta, correct_index, sort_order) values ((select id from quizzes where lesson_id = (select id from lessons where slug = 'counting-to-20')), 'You have 5 mangoes and eat 2. How many are left?', 'අඹ 5 න් 2 ක කෑවොත් ඉතිරි කීයද?', '5 மாம்பழங்களில் 2 சாப்பிட்டால் மீதி எத்தனை?', '["2","4","3","7"]', '["2","4","3","7"]', '["2","4","3","7"]', 2, 3);
