insert into quiz_questions (quiz_id, prompt_en, prompt_si, prompt_ta, choices_en, choices_si, choices_ta, correct_index, sort_order) values ((select id from quizzes where lesson_id = (select id from lessons where slug = 'plant-and-animal-cells')), 'Which part holds the cell''s instructions?', 'සෛලයේ උපදෙස් තියෙන්නේ කොයි කොටසේද?', 'செல்லின் ஆணைகள் எந்தப் பகுதியில் இருக்கும்?', '["Cell wall","Nucleus","Chloroplast","Bone"]', '["සෛල බිත්තිය","න්‍යෂ්ටිය","හරිතලව","අස්ථිය"]', '["செல் சுவர்","உட்கரு","பசும்பகுதி","எலும்பு"]', 1, 1);
insert into quiz_questions (quiz_id, prompt_en, prompt_si, prompt_ta, choices_en, choices_si, choices_ta, correct_index, sort_order) values ((select id from quizzes where lesson_id = (select id from lessons where slug = 'plant-and-animal-cells')), 'Animal cells do not have a…', 'සත්ව සෛලවල නැත්තේ…', 'விலங்கு செல்களுக்கு இல்லாதது…', '["membrane","cell wall","cytoplasm","nucleus"]', '["පටලය","සෛල බිත්තිය","සෛල ප්ලාස්මය","න්‍යෂ්ටිය"]', '["சவ்வு","செல் சுவர்","குழியவுரு","உட்கரு"]', 1, 2);
insert into quiz_questions (quiz_id, prompt_en, prompt_si, prompt_ta, choices_en, choices_si, choices_ta, correct_index, sort_order) values ((select id from quizzes where lesson_id = (select id from lessons where slug = 'plant-and-animal-cells')), 'Living things are made of…', 'ජීවීන් සෑදී ඇත්තේ…', 'உயிரிகள் எவற்றால் ஆனவை…', '["rocks","cells","plastic","clouds"]', '["ගල්","සෛල","ප්ලාස්ටික්","වලාකුළු"]', '["பாறைகள்","செல்கள்","நெகிழி","மேகங்கள்"]', 1, 3);
insert into quizzes (lesson_id, pass_percent) values ((select id from lessons where slug = 'pythagoras-theorem'), 67);
insert into quiz_questions (quiz_id, prompt_en, prompt_si, prompt_ta, choices_en, choices_si, choices_ta, correct_index, sort_order) values ((select id from quizzes where lesson_id = (select id from lessons where slug = 'pythagoras-theorem')), 'A right triangle has shorter sides 3 and 4. The hypotenuse is…', 'කෙටි පැති 3 සහ 4 නම් කර්ණය…', 'சிறிய பக்கங்கள் 3 மற்றும் 4 என்றால் கர்ணம்…', '["5","6","7","12"]', '["5","6","7","12"]', '["5","6","7","12"]', 0, 1);
insert into quiz_questions (quiz_id, prompt_en, prompt_si, prompt_ta, choices_en, choices_si, choices_ta, correct_index, sort_order) values ((select id from quizzes where lesson_id = (select id from lessons where slug = 'pythagoras-theorem')), 'The hypotenuse is the side…', 'කර්ණය යනු… පැත්තයි', 'கர்ணம் என்பது… பக்கம்', '["opposite the right angle","the shortest side","always vertical","outside the triangle"]', '["සෘජු කෝණයට මුහුණලා","කෙටිම පැත්ත","සැමවිට සිරස්","ත්‍රිකෝණයෙන් පිටත"]', '["செங்கோணத்திற்கு எதிரே","மிகச் சிறிய பக்கம்","எப்போதும் செங்குத்து","முக்கோணத்திற்கு வெளியே"]', 0, 2);
insert into quiz_questions (quiz_id, prompt_en, prompt_si, prompt_ta, choices_en, choices_si, choices_ta, correct_index, sort_order) values ((select id from quizzes where lesson_id = (select id from lessons where slug = 'pythagoras-theorem')), 'Which equation is Pythagoras?', 'පයිතගරස් සමීකරණය කුමක්ද?', 'பித்தாகரஸ் சமன்பாடு எது?', '["a + b = c","a² + b² = c²","a × b = c","a² − b = c"]', '["a + b = c","a² + b² = c²","a × b = c","a² − b = c"]', '["a + b = c","a² + b² = c²","a × b = c","a² − b = c"]', 1, 3);
